export function Logo({ className, padel = '#FB2324', title = 'BROX Padel' }: { className?: string; padel?: string; title?: string }) {
  return (
    <svg viewBox="12.8 6.0 913.8 313.5" className={clsx('block', className)} role="img" aria-label={title}>
      <path fill="currentColor" d={BROX} />
      <path fill={padel} d={PADEL} />
    </svg>
  );
}

export function BMark({ className, title }: { className?: string; title?: string }) {
  return (
    <svg viewBox="21.8 38.0 108.4 73.1" className={clsx('block', className)} role={title ? 'img' : undefined} aria-label={title} aria-hidden={title ? undefined : true}>
      <path fill="currentColor" d={B} />
    </svg>
  );
}
